# Published text of the 24 in-scope PCM seeds (17 validated Units 1-3 + 7 held), transcribed from Production published versions.
C={}
def add(n,stem,ch): C['apphycm-mcq-%03d'%n]=(stem,ch)
add(1,"If v(t)=3t², the acceleration at t=2 s is\n\nA. 3 m/s²\nB. 6 m/s²\nC. 12 m/s²\nD. 24 m/s²",[("A","3 m/s²",0,"Mistakes the leading coefficient 3 in v(t)=3t² for the acceleration itself, as in the x=½at² form."),("B","6 m/s²",0,"Mistakenly differentiates v(t)=3t² using an incomplete power rule (dropping the exponent multiplier), computing dv/dt=3t instead of the correct 6t, then evaluates 3(2)=6 m/s² at the correct time t=2 s."),("C","12 m/s²",1,"dv/dt=6t, evaluated at t=2 s gives 12 m/s²."),("D","24 m/s²",0,"Multiplies 6t by t again instead of substituting t=2, giving 6t²=6(2)²=24.")])
add(2,"The displacement from t=0 to T for v(t)=kt is\n\nA. kT\nB. kT²\nC. kT²/2\nD. k/T",[("A","kT",0,"Uses the final velocity v(T)=kT times T instead of integrating the linearly increasing velocity, skipping the 1/2 averaging factor."),("B","kT²",0,"Integrates kt dt to kT² but drops the 1/2 factor that comes from the power rule."),("C","kT²/2",1,"integrating kt gives kT²/2"),("D","k/T",0,"Divides the acceleration constant k by T instead of integrating velocity over time, confusing acceleration units with displacement.")])
add(3,"A force F(x)=ax acts in one dimension. The work from 0 to L is\n\nA. aL\nB. aL²\nC. aL²/2\nD. a/L",[("A","aL",0,"Mistakes the endpoint force value F(L)=aL for the work itself, without multiplying by the displacement."),("B","aL²",0,"Multiplies the endpoint force F(L)=aL by the full distance L as if the force were constant, missing the 1/2 factor from integrating the linearly increasing force."),("C","aL²/2",1,"the integral of ax dx is aL²/2"),("D","a/L",0,"Divides the force gradient a by L, confusing the differential relationship dF/dx=a with the work integral.")])
add(6,"A particle moves in one dimension under a conservative force with potential energy U(x). The force on the particle is given by which of the following?\n\nA. dU/dx\nB. -dU/dx\nC. -U/x\nD. +d^2U/dx^2",[("A","dU/dx",0,"Drops the negative sign, forgetting that force opposes (rather than follows) the direction of increasing potential energy."),("B","-dU/dx",1,"force is the negative potential gradient"),("C","-U/x",0,"This has the correct sign but treats the relationship as simple division rather than differentiation, as though U were directly proportional to x -- it agrees with -dU/dx only in that special case."),("D","+d^2U/dx^2",0,"This differentiates U twice and drops the sign. The second derivative describes how steeply the force itself changes with position (related to the stiffness of the potential well), not the force.")])
add(7,"A power law P(t)=ct² delivers energy from 0 to T equal to\n\nA. cT²\nB. cT³/2\nC. cT³/3\nD. 2cT",[("A","cT²",0,"Evaluates the power at time T and treats that instantaneous value as the total energy, without integrating over the interval."),("B","cT³/2",0,"Integrates ct² correctly in form but uses the wrong power-rule denominator, writing t³/2 instead of t³/3."),("C","cT³/3",1,"energy is the time integral of power"),("D","2cT",0,"Differentiates P(t)=ct² instead of integrating it, computing d/dt(ct²)=2ct and evaluating at T.")])
add(8,"At a stable equilibrium x₀, U(x) has\n\nA. a local minimum\nB. a local maximum\nC. an infinite slope\nD. no derivative",[("A","a local minimum",1,"small displacements raise potential energy"),("B","a local maximum",0,"Confuses stable equilibrium with unstable equilibrium, where the potential sits at a local maximum instead."),("C","an infinite slope",0,"Assumes equilibrium requires the slope to blow up rather than vanish, misreading dU/dx=0 as an undefined or infinite condition."),("D","no derivative",0,"Assumes equilibrium points must be non-smooth kinks in U(x) rather than smooth minima where dU/dx=0.")])
add(12,"Torque from potential energy U(θ), for a system whose potential energy depends only on the angle θ, is\n\nA. dU/dθ\nB. -dU/dθ\nC. -U/θ\nD. +d²U/dθ²",[("A","dU/dθ",0,"Drops the negative sign, forgetting that torque opposes the direction of increasing potential energy."),("B","-dU/dθ",1,"generalized force is minus the potential derivative"),("C","-U/θ",0,"Incorrect. Treats torque as the total potential energy divided by the angle (a ratio), rather than as the instantaneous rate of change of potential energy with angle (a derivative)."),("D","+d²U/dθ²",0,"Incorrect. This is the second derivative of U with respect to θ (related to the curvature/stiffness of the potential, as appears in small-angle oscillation problems), not the first derivative that defines torque.")])
add(17,"If x(t)=At³-Bt, velocity is\n\nA. 3At²-B\nB. At²-B\nC. 3At-B\nD. A t³",[("A","3At²-B",1,"differentiate position with respect to time"),("B","At²-B",0,"Drops the coefficient 3 that the power rule brings down from At³, reducing the exponent without multiplying by it."),("C","3At-B",0,"Reduces the exponent on At³ by one too many, an off-by-one power-rule slip giving t instead of t²."),("D","A t³",0,"Forgets to differentiate the At³ term at all and drops the -Bt term entirely, leaving the position expression unchanged.")])
add(18,"A force F(x)=F₀e^{-x/L} acts along the direction of displacement, with L a positive constant. The work done as the object moves from x=0 to x→∞ is\n\nA. F₀/L\nB. F₀L\nC. zero\nD. infinite",[("A","F₀/L",0,"Inverts the decay length, dividing by L instead of multiplying, as if the integral shrank rather than scaled by the decay length."),("B","F₀L",1,"The integral ∫₀^∞ F₀e^{-x/L}dx = F₀L converges because L>0 makes the exponential decay (not grow) as x increases."),("C","zero",0,"Assumes the force decaying to zero as x→∞ means the enclosed area (work) also vanishes, rather than converging to a finite nonzero value."),("D","infinite",0,"Assumes an infinite integration limit must always produce infinite work, missing that the exponential integrand decays fast enough to converge.")])
add(19,"For τ(t)=τ₀t acting on constant I, change in angular speed from 0 to T is\n\nA. τ₀T/I\nB. τ₀T²/(2I)\nC. Iτ₀T²\nD. τ₀T²/I",[("A","τ₀T/I",0,"This applies the constant-torque impulse formula Δω=τT/I using τ0 as if it were the full (constant) torque magnitude, rather than recognizing τ(t)=τ0t is linearly increasing -- τ0 here is only a proportionality constant, not the torque itself -- so integration is required, introducing the T² (not T) time dependence."),("B","τ₀T²/(2I)",1,"Integrating α=τ(t)/I=τ0t/I over time from 0 to T gives Δω=τ0T²/(2I)."),("C","Iτ₀T²",0,"Multiplies by I instead of dividing by it, inverting where the moment of inertia belongs in α=τ/I."),("D","τ₀T²/I",0,"Integrates in the correct form but omits the 1/2 factor that comes from integrating t dt.")])
add(20,"For a physical pendulum undergoing small-angle oscillation, omega^2 equals which of the following, where d is the distance from the pivot to the center of mass and I is the moment of inertia about the pivot?\n\nA. mgd/I\nB. I/mgd\nC. g/I\nD. mgI/d",[("A","mgd/I",1,"linearizing Iθ''=-mgdθ gives ω²=mgd/I"),("B","I/mgd",0,"Inverts the correct ratio, swapping the numerator and denominator of mgd/I."),("C","g/I",0,"Drops the mass m and pivot distance d from the numerator, misapplying the simple pendulum's g/L form instead of adapting for the physical pendulum's torque equation."),("D","mgI/d",0,"Multiplies by I instead of dividing by it, inverting where the moment of inertia belongs in the ratio.")])
add(21,"For x(t)=Ct⁴, acceleration is\n\nA. 4Ct³\nB. 12Ct²\nC. 24Ct\nD. Ct²",[("A","4Ct³",0,"This is the first derivative, velocity, rather than acceleration."),("B","12Ct²",1,"Two time derivatives give v=4Ct³ and a=12Ct²."),("C","24Ct",0,"This takes a third derivative and therefore gives jerk."),("D","Ct²",0,"This reduces the exponent without applying the power-rule coefficients.")])
add(22,"The signed area under a velocity-versus-time graph equals\n\nA. acceleration\nB. displacement\nC. distance traveled\nD. change in velocity",[("A","acceleration",0,"Acceleration is the slope of velocity versus time, not its area."),("B","displacement",1,"The time integral of velocity is the signed change in position."),("C","distance traveled",0,"Distance traveled adds all areas as positive, but signed velocity-time area gives displacement."),("D","change in velocity",0,"Change in velocity comes from integrating acceleration, not velocity.")])
add(23,"A block slides down a frictionless incline at angle θ. The normal force on the block is\n\nA. mg\nB. mg sinθ\nC. mg cosθ\nD. 0",[("A","mg",0,"This ignores the incline angle and uses the full weight."),("B","mg sinθ",0,"This is the component parallel to the incline, not perpendicular."),("C","mg cosθ",1,"The normal force balances the perpendicular weight component mg cosθ."),("D","0",0,"Frictionless means no frictional force; the incline still exerts a normal force.")])
add(24,"For U(x)=(1/2)kx² with k>0, x=0 is stable because\n\nA. U has a local minimum\nB. U has a local maximum\nC. force is constant\nD. energy is negative",[("A","U has a local minimum",1,"The potential has positive curvature and a local minimum at equilibrium."),("B","U has a local maximum",0,"A local maximum corresponds to unstable equilibrium."),("C","force is constant",0,"The force -kx varies with position and is not constant."),("D","energy is negative",0,"The chosen potential is nonnegative and energy sign is not the stability criterion.")])
add(25,"For m dv/dt=-bv, the characteristic decay time is\n\nA. b/m\nB. m/b\nC. m/(2b)\nD. (m/b) ln 2",[("A","b/m",0,"This is the decay rate with units of inverse time, not the time constant."),("B","m/b",1,"The solution e^{-bt/m} has time constant τ=m/b."),("C","m/(2b)",0,"This confuses the velocity-decay time with the faster decay time of kinetic energy."),("D","(m/b) ln 2",0,"This is the half-life, not the characteristic velocity-decay time m/b.")])
add(26,"A particle in uniform circular motion has\n\nA. zero acceleration\nB. constant velocity vector\nC. inward acceleration v²/r\nD. outward net force",[("A","zero acceleration",0,"This confuses constant speed with zero acceleration."),("B","constant velocity vector",0,"The velocity vector rotates continuously and is not constant."),("C","inward acceleration v²/r",1,"Its changing velocity direction requires inward acceleration v²/r."),("D","outward net force",0,"The net force is inward; an outward force is not required in an inertial frame.")])
add(27,"The work done from x=a to x=b by F(x) is\n\nA. ∫ₐᵇF(x)dx\nB. F(b)(b-a)\nC. (1/2)[F(a)+F(b)](b-a) always\nD. ∫F(t)dt",[("A","∫ₐᵇF(x)dx",1,"Mechanical work along x is the position integral of force over the path."),("B","F(b)(b-a)",0,"This assumes the final force acts constantly over the entire displacement."),("C","(1/2)[F(a)+F(b)](b-a) always",0,"Endpoint averaging is exact only when force varies linearly with position."),("D","∫F(t)dt",0,"A time integral of force is impulse, not work.")])
add(28,"For U(x)=Ax³, the force is\n\nA. 3Ax²\nB. -3Ax²\nC. -Ax²\nD. -(A/3)x²",[("A","3Ax²",0,"This takes the derivative but omits the required negative sign."),("B","-3Ax²",1,"The negative spatial derivative gives F=-dU/dx=-3Ax²."),("C","-Ax²",0,"This keeps the negative sign but omits the power-rule factor three."),("D","-(A/3)x²",0,"This divides by the exponent instead of multiplying by it when differentiating Ax³.")])
add(29,"At a one-dimensional classical turning point with total energy E,\n\nA. U=0 always\nB. U=E and speed is zero\nC. force must be zero\nD. kinetic energy is maximum",[("A","U=0 always",0,"Potential zero depends on reference choice and is not the turning criterion."),("B","U=E and speed is zero",1,"At a turning point K=0, so total energy equals potential energy."),("C","force must be zero",0,"Force can be nonzero at a turning point and reverse the motion."),("D","kinetic energy is maximum",0,"Kinetic energy is zero rather than maximum at the turning point.")])
add(30,"A force F acts on a particle with velocity v. Instantaneous power is\n\nA. F·v\nB. F×v\nC. Fv regardless of direction\nD. F·a",[("A","F·v",1,"Instantaneous mechanical power is the scalar product F·v."),("B","F×v",0,"A cross product gives a vector and does not represent energy-transfer rate."),("C","Fv regardless of direction",0,"This ignores the angle between force and velocity; only the parallel force component contributes to power."),("D","F·a",0,"Instantaneous power depends on velocity, not acceleration.")])
add(31,"For constant mass m and v(t), net force equals\n\nA. mv/t\nB. m dv/dt\nC. v dm/dt only\nD. (1/2)m dv/dt",[("A","mv/t",0,"This assumes acceleration always equals velocity divided by time, ignoring initial velocity and how velocity varies."),("B","m dv/dt",1,"For constant mass, F=dp/dt=m dv/dt."),("C","v dm/dt only",0,"This term applies to mass change and omits ordinary acceleration."),("D","(1/2)m dv/dt",0,"This incorrectly carries the one-half factor from kinetic energy into Newton's second law.")])
add(34,"In an isolated perfectly inelastic collision,\n\nA. momentum and kinetic energy are conserved\nB. momentum is conserved but kinetic energy is not\nC. kinetic energy is conserved but momentum is not\nD. neither total energy nor momentum is conserved",[("A","momentum and kinetic energy are conserved",0,"This incorrectly treats sticking as an elastic interaction."),("B","momentum is conserved but kinetic energy is not",1,"Isolation conserves momentum, while sticking converts some kinetic energy to internal energy."),("C","kinetic energy is conserved but momentum is not",0,"This reverses the two conservation results."),("D","neither total energy nor momentum is conserved",0,"Total energy and momentum remain conserved; only kinetic energy decreases.")])
add(40,"For circular orbits about the same mass, doubling radius multiplies period by\n\nA. sqrt2\nB. 2\nC. 2sqrt2\nD. 4",[("A","sqrt2",0,"This uses the orbital-speed square-root factor instead of period scaling."),("B","2",0,"This assumes period is directly proportional to radius."),("C","2sqrt2",1,"Kepler scaling T∝r^{3/2} gives 2^{3/2}=2sqrt2."),("D","4",0,"This applies a square dependence rather than the three-halves power.")])
